bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker exec "$cid" grep -Fq "'getMyStarBalance'" /opt/videobot/src/telegram/botApi.mjs || exit 63
docker exec "$cid" test -f /opt/videobot/src/sales/pgCreatorRefundReconciler.mjs || exit 64
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
setDefaultResultOrder('ipv4first');
setDefaultAutoSelectFamily(false);
const path=process.env.VIDEOBOT_TELEGRAM_TOKEN_FILE;
if(typeof path!=='string'||!path.startsWith('/run/secrets/'))process.exit(65);
const token=readFileSync(path,'utf8').trim();
const api=createTelegramBotApi({token,
 baseUrl:process.env.VIDEOBOT_LOCAL_API_URL||'https://api.telegram.org',
 timeoutMs:25000});
try{
 const balance=await api('getMyStarBalance',{});
 if(!Number.isSafeInteger(balance?.amount)||balance.amount<0)
   throw Error('OFFICIAL_STARS_BALANCE_INVALID');
 console.log('OFFICIAL_BOT_STARS_BALANCE=READ_VERIFIED');
}catch(error){console.log('OFFICIAL_BOT_STARS_BALANCE=NOT_VERIFIED');process.exit(66);}
try{
 const result=await api('getStarTransactions',{offset:0,limit:5});
 if(!Array.isArray(result?.transactions)||result.transactions.length>5)
   throw Error('OFFICIAL_TRANSACTIONS_INVALID');
 console.log('OFFICIAL_BOT_STARS_TRANSACTIONS=READ_VERIFIED');
}catch(error){console.log('OFFICIAL_BOT_STARS_TRANSACTIONS=NOT_VERIFIED');process.exit(67);}
NODE
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createPostgresUnifiedStarsSales} from './src/sales/pgUnifiedStarsSales.mjs';
const env=process.env;
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,
 database:env.VIDEOBOT_DB_NAME,
 password:readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 max:1,connectionTimeoutMillis:5000});
try{
 const q=await pool.query("SELECT to_regclass('videobot_sticker_refunds') IS NOT NULL AS refunds,to_regclass('videobot_stars_refund_audit_cursor') IS NOT NULL AS cursor");
 if(q.rows.length!==1||q.rows[0].refunds!==true||q.rows[0].cursor!==true)
  throw Error('REFUND_LEDGER_SCHEMA_MISSING');
 const sample=await pool.query("SELECT seller_user_id FROM videobot_stars_ledger UNION SELECT seller_user_id FROM videobot_sticker_products LIMIT 1");
 const id=sample.rows.length?Number(sample.rows[0].seller_user_id):1;
 const summary=await createPostgresUnifiedStarsSales({pool}).getSummary(id);
 if(summary.payoutReady!==false)throw Error('UNVERIFIED_PAYOUT_EXPOSED');
 const cursor=await pool.query("SELECT next_offset FROM videobot_stars_refund_audit_cursor WHERE cursor_id=1");
 if(cursor.rows.length>1)throw Error('AUDIT_CURSOR_DUPLICATE');
 console.log('STARS_REAL_PG_SELLER_ACCOUNTING=READ_VERIFIED');
}catch(error){console.log('STARS_REAL_PG_SELLER_ACCOUNTING=NOT_VERIFIED');process.exitCode=68;
}finally{await pool.end();}
NODE
echo OFFICIAL_STARS_READONLY_E2E=PASS
